      "text6fdb8f60b253": "Click to copy",
      "text063bbc13dd0b": "Scaffold and ship",
      "textda973557600d": "Scaffold kortix.yaml, agents/ and skills/",
      "text79dd44846e0d": "Commit, push, link and go live",
      "text486864310b65": "Type-check your manifest",
      "text71fa5ca5ed8c": "Run and talk",
      "text9cb07bbec07e": "Start and manage sandbox sessions",
      "textafe984cb68d5": "Talk to a session's agent",
